def main():
    default_decompress = "unpigz" in os.path.basename(sys.argv[0])

    env_args = []
    for envvar in ("GZIP","PIGZ"):
        v = os.environ.get(envvar)
        if v:
            try:
                env_args.extend(shlex.split(v))
            except:
                env_args.extend(v.split())

    raw_args = env_args + sys.argv[1:]

    opts = {
        'decompress': default_decompress,
        'to_stdout': False,
        'force': False,
        'keep': False,
        'list': False,
        'test': False,
        'verbose': False,
        'quiet': False,
        'recursive': False,
        'independent': False,
        'rsyncable': False,
        'huffman': False,
        'rle': False,
        'zip': False,
        'zlib': False,
        'first': False,
        'oneblock': False,
        'sync': False,
        'blocksize': 128,
        'processes': None,
        'iterations': 15,
        'maxsplits': 15,
        'alias': None,
        'comment': None,
        'suffix': None,
        'level': 6,
        'help': False,
        'version': False,
        'license': False,
        'store_name': True,
        'store_time': True,
    }

    name_flag = None
    time_flag = None

    first_hvl = None

    last_dt = None

    list_seen = False

    files = []
    after_dashdash = False
    idx = 0
    while idx < len(raw_args):
        arg = raw_args[idx]
        if after_dashdash:
            files.append(arg)
            idx+=1
            continue
        if arg == "--":
            after_dashdash=True
            idx+=1
            continue
        if arg == "-":
            files.append(arg)
            idx+=1
            continue
        if arg.startswith("--"):
            if "=" in arg:
                abort(f"invalid option: {arg}")
            name = arg[2:]
            if name == "help":
                opts['help']=True
                if first_hvl is None:
                    first_hvl='h'
            elif name == "version":
                opts['version']=True
                if first_hvl is None:
                    first_hvl='V'
            elif name == "license":
                opts['license']=True
                if first_hvl is None:
                    first_hvl='L'
            elif name in ("stdout","to-stdout"):
                opts['to_stdout']=True
            elif name in ("decompress","uncompress"):
                opts['decompress']=True
                last_dt='d'
            elif name == "force":
                opts['force']=True
            elif name == "first":
                opts['first']=True
            elif name == "huffman":
                opts['huffman']=True
            elif name == "independent":
                opts['independent']=True
            elif name == "keep":
                opts['keep']=True
            elif name == "zip":
                opts['zip']=True
            elif name == "list":
                opts['list']=True
                list_seen=True
            elif name == "no-time":
                time_flag=False
            elif name == "time":
                time_flag=True
            elif name == "no-name":
                name_flag=False
                time_flag=False
            elif name == "name":
                name_flag=True
                time_flag=True
            elif name == "oneblock":
                opts['oneblock']=True
            elif name in ("quiet","silent"):
                opts['quiet']=True
            elif name == "recursive":
                opts['recursive']=True
            elif name == "rsyncable":
                opts['rsyncable']=True
            elif name == "test":
                opts['test']=True
                last_dt='t'
            elif name == "rle":
                opts['rle']=True
            elif name == "verbose":
                opts['verbose']=True
            elif name == "synchronous":
                opts['sync']=True
            elif name == "zlib":
                opts['zlib']=True
            elif name == "fast":
                opts['level']=1
            elif name == "best":
                opts['level']=9
            elif name in ("alias","comment","blocksize","processes","suffix","iterations","maxsplits"):
                if idx+1 >= len(raw_args):
                    short_map = {"alias":"A","comment":"C","blocksize":"b","processes":"p","suffix":"S","iterations":"I","maxsplits":"J"}
                    abort(f"missing parameter after -{short_map[name]}")
                val = raw_args[idx+1]
                if name == "alias":
                    opts['alias']=val
                elif name == "comment":
                    opts['comment']=val
                elif name == "blocksize":
                    v = parse_numeric_param(val)
                    if v < 32:
                        abort("block size too small (must be >= 32K)")
                    opts['blocksize']=v
                elif name == "processes":
                    v = parse_numeric_param(val)
                    if v <=0:
                        abort(f"invalid number of processes: {v}")
                    opts['processes']=v
                elif name == "suffix":
                    opts['suffix']=val
                elif name == "iterations":
                    v = parse_numeric_param(val)
                    opts['iterations']=v
                elif name == "maxsplits":
                    v = parse_numeric_param(val)
                    opts['maxsplits']=v
                idx+=1
            else:
                abort(f"invalid option: --{name}")
            idx+=1
            continue
        elif arg.startswith("-") and len(arg)>1:
            j=1
            while j < len(arg):
                ch = arg[j]
                if ch.isdigit():
                    num_str=""
                    k=j
                    while k < len(arg) and arg[k].isdigit():
                        num_str+=arg[k]
                        k+=1
                    if num_str in [str(d) for d in range(10)]+["11"]:
                        opts['level']=int(num_str)
                        j=k
                        continue
                    else:
                        abort("only levels 0..9 and 11 are allowed")
                if ch in ('A','b','C','I','J','p','S'):
                    remainder = arg[j+1:]
                    if ch in ('S','C'):
                        if remainder!="":
                            abort(f"invalid usage: -{ch} must be followed by space")
                        if idx+1 >= len(raw_args):
                            abort(f"missing parameter after -{ch}")
                        param = raw_args[idx+1]
                        if ch=='S':
                            opts['suffix']=param
                        else:
                            opts['comment']=param
                        idx+=1
                        break
                    else:
                        if remainder!="":
                            param=remainder
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            break
                        else:
                            if idx+1 >= len(raw_args):
                                abort(f"missing parameter after -{ch}")
                            param=raw_args[idx+1]
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            idx+=1
                            break
                else:
                    if ch=='c':
                        opts['to_stdout']=True
                    elif ch=='d':
                        opts['decompress']=True
                        last_dt='d'
                    elif ch=='f':
                        opts['force']=True
                    elif ch=='h':
                        opts['help']=True
                        if first_hvl is None:
                            first_hvl='h'
                    elif ch=='H':
                        opts['huffman']=True
                    elif ch=='i':
                        opts['independent']=True
                    elif ch=='k':
                        opts['keep']=True
                    elif ch=='K':
                        opts['zip']=True
                    elif ch=='l':
                        opts['list']=True
                        list_seen=True
                    elif ch=='L':
                        opts['license']=True
                        if first_hvl is None:
                            first_hvl='L'
                    elif ch=='m':
                        time_flag=False
                    elif ch=='M':
                        time_flag=True
                    elif ch=='n':
                        name_flag=False
                        time_flag=False
                    elif ch=='N':
                        name_flag=True
                        time_flag=True
                    elif ch=='O':
                        opts['oneblock']=True
                    elif ch=='q':
                        opts['quiet']=True
                    elif ch=='r':
                        opts['recursive']=True
                    elif ch=='R':
                        opts['rsyncable']=True
                    elif ch=='t':
                        opts['test']=True
                        last_dt='t'
                    elif ch=='U':
                        opts['rle']=True
                    elif ch=='v':
                        opts['verbose']=True
                    elif ch=='V':
                        opts['version']=True
                        if first_hvl is None:
                            first_hvl='V'
                    elif ch=='Y':
                        opts['sync']=True
                    elif ch=='z':
                        opts['zlib']=True
                    elif ch=='F':
                        opts['first']=True
                    else:
                        abort(f"invalid option: -{ch}")
                    j+=1
            idx+=1
            continue
        else:
            files.append(arg)
            idx+=1

    if first_hvl is not None:
        if first_hvl=='h':
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        elif first_hvl=='V':
            if opts['verbose']:
                sys.stdout.write(f"pigz {VERSION}\nzlib {ZLIB_VERSION}\n")
            else:
                sys.stdout.write(f"pigz {VERSION}\n")
            sys.exit(0)
        elif first_hvl=='L':
            sys.stdout.write(LICENSE_TEXT)
            sys.exit(0)

    if opts['list']:
        if not files:
            files=["-"]
        code = list_files(files, opts['verbose'], opts['quiet'])
        sys.exit(code)

    # Determine mode: test vs decompress
    is_decompress=False
    is_test=False
    if last_dt is not None:
        if last_dt=='d':
            is_decompress=True
        else:
            is_test=True
    else:
        is_decompress=opts['decompress']
        is_test=opts['test']

    # Final store flags
    if not is_decompress and not is_test:
        final_name = name_flag if name_flag is not None else True
        final_time = time_flag if time_flag is not None else True
    else:
        final_name = name_flag if name_flag is not None else False
        final_time = time_flag if time_flag is not None else False
    opts['store_name']=final_name
    opts['store_time']=final_time
    opts['test']=is_test

    comp_suffix = get_output_suffix(opts)

    exit_code=0

    def process_compress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write("<stdin> to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=None, is_file=False)
            return
        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath = os.path.join(root, fname)
                        process_compress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if in_path.endswith(comp_suffix) and not opts['force']:
            skip(f"{in_path} ends with {comp_suffix}", opts['quiet'])
            return
        out_path = in_path + comp_suffix
        if not opts['to_stdout']:
            if os.path.exists(out_path) and not opts['force']:
                skip(f"{out_path} exists", opts['quiet'])
                exit_code=1
                return
        try:
            with open(in_path, 'rb') as f:
                data = f.read()
        except:
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if opts['to_stdout']:
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=in_path, is_file=True)
        else:
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to {out_path} \n")
            try:
                compress_file_to_path(in_path, out_path, opts)
            except Exception as e:
                # Check if output exists error already handled?
                skip(f"{out_path} exists" if os.path.exists(out_path) else str(e), opts['quiet'])
                exit_code=1
                return
            if not opts['keep']:
                try:
                    os.remove(in_path)
                except:
                    pass

    def process_decompress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if len(data)==0:
                skip("<stdin> empty", opts['quiet'])
                exit_code=1
                return
            is_gzip = data[0:2]==b'\x1f\x8b' if len(data)>=2 else False
            is_zip = data[0:4]==b'PK\x03\x04' if len(data)>=4 else False
            is_zlib = False
            if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
                return
            try:
                if is_gzip:
                    bio = io.BytesIO(data)
                    with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                        dec = gf.read()
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zlib:
                    dec = zlib.decompress(data)
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zip:
                    with zipfile.ZipFile(io.BytesIO(data)) as zf:
                        dec = zf.read(zf.infolist()[0].filename)
                        if opts['test']:
                            return
                        sys.stdout.buffer.write(dec)
                        if opts['verbose']:
                            sys.stderr.write("<stdin> to <stdout> \n")
            except:
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
            return

        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath = os.path.join(root, fname)
                        process_decompress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        try:
            if os.path.getsize(in_path)==0:
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
                return
        except:
            pass

        # Suffix check for decompress unless to_stdout
        if not opts['to_stdout']:
            # Determine expected output name
            out_name = get_stripped_name(in_path, opts['suffix'])
            # Check suffix
            if opts['suffix'] is not None:
                # Must end with suffix
                if not in_path.endswith(opts['suffix']):
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
                # Additionally, if suffix not in allowed list, fail (replicate buggy behavior)
                if opts['suffix'] not in ALLOWED_SUFFIXES:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            else:
                # No custom suffix, must end with allowed
                found=False
                for suf in ALLOWED_SUFFIXES:
                    if in_path.endswith(suf):
                        found=True
                        break
                if not found:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            if out_name is None:
                skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                exit_code=1
                return
            # Check if output exists and not force
            if os.path.exists(out_name) and not opts['force']:
                skip(f"{out_name} exists", opts['quiet'])
                exit_code=1
                return
        else:
            out_name = None

        # Now decompress
        # Use decompress_file_to_path
        has_junk, status = decompress_file_to_path(in_path, out_name, opts, to_stdout=opts['to_stdout'])
        if status != "ok":
            if status == "empty":
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
            elif status == "unrecognized":
                skip(f"{in_path} unrecognized format", opts['quiet'])
                exit_code=1
            elif status == "notfound":
                skip(f"{in_path} does not exist", opts['quiet'])
                exit_code=1
            else:
                skip(f"{in_path} unrecognized format", opts['quiet'])
                exit_code=1
            return
