                    os.utime(out_path, (st.st_atime, st.st_mtime))
                except:
                    pass
                return False, "ok"
        elif is_zip:
            with zipfile.ZipFile(io.BytesIO(all_data), 'r') as zf:
                infos = zf.infolist()
                if not infos:
                    return None, "unrecognized"
                info = infos[0]
                dec = zf.read(info.filename)
            if to_stdout:
                sys.stdout.buffer.write(dec)
                return False, "ok"
            else:
                with open(out_path, 'wb') as out:
                    out.write(dec)
                    if opts['sync']:
                        out.flush()
                        os.fsync(out.fileno())
                if opts['store_time']:
                    try:
                        dt = datetime.datetime(*info.date_time)
                        mtime = dt.timestamp()
                        os.utime(out_path, (mtime, mtime))
                    except:
                        try:
                            os.utime(out_path, (st.st_atime, st.st_mtime))
                        except:
                            pass
                else:
                    try:
                        os.utime(out_path, (st.st_atime, st.st_mtime))
                    except:
                        pass
                return False, "ok"
    except Exception as e:
        return None, "unrecognized"

def list_files(file_list, verbose, quiet):
    exit_code = 0
    if verbose:
        print("method    check    timestamp    compressed   original reduced  name")
    else:
        print("compressed   original reduced  name")
    for path in file_list:
        if path == "-":
            # stdin
            data = sys.stdin.buffer.read()
