def main():
    default_decompress = "unpigz" in os.path.basename(sys.argv[0])

    env_args = []
    for envvar in ("GZIP","PIGZ"):
        v = os.environ.get(envvar)
        if v:
            try:
                env_args.extend(shlex.split(v))
            except:
                env_args.extend(v.split())

    raw_args = env_args + sys.argv[1:]

    opts = {
        'decompress': default_decompress,
        'to_stdout': False,
        'force': False,
        'keep': False,
        'list': False,
        'test': False,
        'verbose': False,
        'quiet': False,
        'recursive': False,
        'independent': False,
        'rsyncable': False,
        'huffman': False,
        'rle': False,
        'zip': False,
        'zlib': False,
        'first': False,
        'oneblock': False,
        'sync': False,
        'blocksize': 128,
        'processes': None,
        'iterations': 15,
        'maxsplits': 15,
        'alias': None,
        'comment': None,
        'suffix': None,
        'level': 6,
        'help': False,
        'version': False,
        'license': False,
        'store_name': True,
        'store_time': True,
    }

    name_flag = None
    time_flag = None

    first_hvl = None

    last_dt = None

    list_seen = False

    files = []
    after_dashdash = False
    idx = 0
    while idx < len(raw_args):
        arg = raw_args[idx]
        if after_dashdash:
            files.append(arg)
            idx+=1
            continue
        if arg == "--":
            after_dashdash=True
            idx+=1
            continue
        if arg == "-":
            files.append(arg)
            idx+=1
            continue
        if arg.startswith("--"):
            if "=" in arg:
                abort(f"invalid option: {arg}")
            name = arg[2:]
            if name == "help":
                opts['help']=True
                if first_hvl is None:
                    first_hvl='h'
            elif name == "version":
                opts['version']=True
                if first_hvl is None:
                    first_hvl='V'
            elif name == "license":
                opts['license']=True
                if first_hvl is None:
                    first_hvl='L'
            elif name in ("stdout","to-stdout"):
                opts['to_stdout']=True
            elif name in ("decompress","uncompress"):
                opts['decompress']=True
                last_dt='d'
            elif name == "force":
                opts['force']=True
            elif name == "first":
                opts['first']=True
            elif name == "huffman":
                opts['huffman']=True
            elif name == "independent":
                opts['independent']=True
            elif name == "keep":
                opts['keep']=True
            elif name == "zip":
                opts['zip']=True
            elif name == "list":
                opts['list']=True
                list_seen=True
            elif name == "no-time":
                time_flag=False
            elif name == "time":
                time_flag=True
            elif name == "no-name":
                name_flag=False
                time_flag=False
            elif name == "name":
                name_flag=True
                time_flag=True
            elif name == "oneblock":
                opts['oneblock']=True
            elif name in ("quiet","silent"):
                opts['quiet']=True
            elif name == "recursive":
                opts['recursive']=True
            elif name == "rsyncable":
                opts['rsyncable']=True
            elif name == "test":
                opts['test']=True
                last_dt='t'
            elif name == "rle":
                opts['rle']=True
            elif name == "verbose":
                opts['verbose']=True
            elif name == "synchronous":
                opts['sync']=True
            elif name == "zlib":
                opts['zlib']=True
            elif name == "fast":
                opts['level']=1
            elif name == "best":
                opts['level']=9
            elif name in ("alias","comment","blocksize","processes","suffix","iterations","maxsplits"):
                if idx+1 >= len(raw_args):
                    short_map = {"alias":"A","comment":"C","blocksize":"b","processes":"p","suffix":"S","iterations":"I","maxsplits":"J"}
                    abort(f"missing parameter after -{short_map[name]}")
                val = raw_args[idx+1]
                if name == "alias":
                    opts['alias']=val
                elif name == "comment":
                    opts['comment']=val
                elif name == "blocksize":
                    v = parse_numeric_param(val)
                    if v < 32:
                        abort("block size too small (must be >= 32K)")
                    opts['blocksize']=v
                elif name == "processes":
                    v = parse_numeric_param(val)
                    if v <=0:
                        abort(f"invalid number of processes: {v}")
                    opts['processes']=v
                elif name == "suffix":
                    opts['suffix']=val
                elif name == "iterations":
                    v = parse_numeric_param(val)
                    opts['iterations']=v
                elif name == "maxsplits":
                    v = parse_numeric_param(val)
                    opts['maxsplits']=v
                idx+=1
            else:
                abort(f"invalid option: --{name}")
            idx+=1
            continue
        elif arg.startswith("-") and len(arg)>1:
            j=1
            while j < len(arg):
                ch = arg[j]
                if ch.isdigit():
                    num_str=""
                    k=j
                    while k < len(arg) and arg[k].isdigit():
                        num_str+=arg[k]
                        k+=1
                    if num_str in [str(d) for d in range(10)]+["11"]:
                        opts['level']=int(num_str)
                        j=k
                        continue
                    else:
                        abort("only levels 0..9 and 11 are allowed")
                if ch in ('A','b','C','I','J','p','S'):
                    remainder = arg[j+1:]
                    if ch in ('S','C'):
                        if remainder!="":
                            abort(f"invalid usage: -{ch} must be followed by space")
                        if idx+1 >= len(raw_args):
                            abort(f"missing parameter after -{ch}")
                        param = raw_args[idx+1]
                        if ch=='S':
                            opts['suffix']=param
                        else:
                            opts['comment']=param
                        idx+=1
                        break
                    else:
                        if remainder!="":
                            param=remainder
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            break
                        else:
                            if idx+1 >= len(raw_args):
                                abort(f"missing parameter after -{ch}")
                            param=raw_args[idx+1]
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            idx+=1
                            break
                else:
                    if ch=='c':
                        opts['to_stdout']=True
                    elif ch=='d':
                        opts['decompress']=True
                        last_dt='d'
                    elif ch=='f':
                        opts['force']=True
                    elif ch=='h':
                        opts['help']=True
                        if first_hvl is None:
                            first_hvl='h'
                    elif ch=='H':
                        opts['huffman']=True
                    elif ch=='i':
                        opts['independent']=True
                    elif ch=='k':
                        opts['keep']=True
                    elif ch=='K':
                        opts['zip']=True
                    elif ch=='l':
                        opts['list']=True
                        list_seen=True
                    elif ch=='L':
                        opts['license']=True
                        if first_hvl is None:
                            first_hvl='L'
                    elif ch=='m':
                        time_flag=False
                    elif ch=='M':
                        time_flag=True
                    elif ch=='n':
                        name_flag=False
                        time_flag=False
                    elif ch=='N':
                        name_flag=True
                        time_flag=True
                    elif ch=='O':
                        opts['oneblock']=True
                    elif ch=='q':
                        opts['quiet']=True
                    elif ch=='r':
                        opts['recursive']=True
                    elif ch=='R':
                        opts['rsyncable']=True
                    elif ch=='t':
                        opts['test']=True
                        last_dt='t'
                    elif ch=='U':
                        opts['rle']=True
                    elif ch=='v':
                        opts['verbose']=True
                    elif ch=='V':
                        opts['version']=True
                        if first_hvl is None:
                            first_hvl='V'
                    elif ch=='Y':
                        opts['sync']=True
                    elif ch=='z':
                        opts['zlib']=True
                    elif ch=='F':
                        opts['first']=True
                    else:
                        abort(f"invalid option: -{ch}")
                    j+=1
            idx+=1
            continue
        else:
            files.append(arg)
            idx+=1

    if first_hvl is not None:
        if first_hvl=='h':
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        elif first_hvl=='V':
