                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            break
                        else:
                            if idx+1 >= len(raw_args):
                                abort(f"missing parameter after -{ch}")
                            param=raw_args[idx+1]
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            idx+=1
                            break
                else:
                    if ch=='c':
                        opts['to_stdout']=True
                    elif ch=='d':
                        opts['decompress']=True
                        last_dt='d'
                    elif ch=='f':
                        opts['force']=True
                    elif ch=='h':
                        opts['help']=True
                        if first_hvl is None:
                            first_hvl='h'
                    elif ch=='H':
                        opts['huffman']=True
                    elif ch=='i':
                        opts['independent']=True
                    elif ch=='k':
                        opts['keep']=True
                    elif ch=='K':
                        opts['zip']=True
                    elif ch=='l':
                        opts['list']=True
                        list_seen=True
                    elif ch=='L':
                        opts['license']=True
                        if first_hvl is None:
                            first_hvl='L'
                    elif ch=='m':
                        time_flag=False
                    elif ch=='M':
                        time_flag=True
                    elif ch=='n':
                        name_flag=False
                        time_flag=False
                    elif ch=='N':
                        name_flag=True
                        time_flag=True
                    elif ch=='O':
                        opts['oneblock']=True
                    elif ch=='q':
                        opts['quiet']=True
                    elif ch=='r':
                        opts['recursive']=True
                    elif ch=='R':
                        opts['rsyncable']=True
                    elif ch=='t':
                        opts['test']=True
                        last_dt='t'
                    elif ch=='U':
                        opts['rle']=True
                    elif ch=='v':
                        opts['verbose']=True
                    elif ch=='V':
                        opts['version']=True
                        if first_hvl is None:
                            first_hvl='V'
                    elif ch=='Y':
                        opts['sync']=True
                    elif ch=='z':
                        opts['zlib']=True
                    elif ch=='F':
                        opts['first']=True
