        elif first_hvl=='L':
            sys.stdout.write(LICENSE_TEXT)
            sys.exit(0)

    if opts['list']:
        if not files:
            files=["-"]
        code = list_files(files, opts['verbose'], opts['quiet'], opts['recursive'])
        sys.exit(code)

    is_decompress=False
    is_test=False
    if last_dt is not None:
        if last_dt=='d':
            is_decompress=True
        else:
            is_test=True
    else:
        is_decompress=opts['decompress']
        is_test=opts['test']

    if not is_decompress and not is_test:
        final_name = name_flag if name_flag is not None else True
        final_time = time_flag if time_flag is not None else True
    else:
        final_name = name_flag if name_flag is not None else False
        final_time = time_flag if time_flag is not None else False
    opts['store_name']=final_name
    opts['store_time']=final_time
    opts['test']=is_test

    comp_suffix = get_output_suffix(opts)

    exit_code=0

    def process_compress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write("<stdin> to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=None, is_file=False)
            return
        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath = os.path.join(root, fname)
                        process_compress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if in_path.endswith(comp_suffix) and not opts['force']:
            skip(f"{in_path} ends with {comp_suffix}", opts['quiet'])
            return
        out_path = in_path + comp_suffix
        if not opts['to_stdout']:
            if os.path.exists(out_path) and not opts['force']:
                skip(f"{out_path} exists", opts['quiet'])
