            return
        if opts['to_stdout']:
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=in_path, is_file=True)
        else:
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to {out_path} \n")
            try:
                compress_file_to_path(in_path, out_path, opts)
            except Exception as e:
                skip(f"{out_path} exists" if os.path.exists(out_path) else str(e), opts['quiet'])
                exit_code=1
                return
            if not opts['keep']:
                try:
                    os.remove(in_path)
                except:
                    pass

    def process_decompress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if len(data)==0:
                skip("<stdin> empty", opts['quiet'])
                exit_code=1
                return
            is_gzip = data[0:2]==b'\x1f\x8b' if len(data)>=2 else False
            is_zip = data[0:4]==b'PK\x03\x04' if len(data)>=4 else False
            is_zlib = False
            if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
                return
            try:
                if is_gzip:
                    bio = io.BytesIO(data)
                    with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                        dec=gf.read()
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zlib:
                    dec=zlib.decompress(data)
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zip:
                    with zipfile.ZipFile(io.BytesIO(data)) as zf:
                        dec=zf.read(zf.infolist()[0].filename)
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
            except:
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
            return

        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath=os.path.join(root,fname)
                        process_decompress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        try:
            if os.path.getsize(in_path)==0:
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
                return
        except:
            pass

        if not opts['to_stdout']:
            # Suffix check
            if opts['suffix'] is not None:
                if not in_path.endswith(opts['suffix']):
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
                if opts['suffix'] not in ALLOWED_SUFFIXES:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            else:
                found=False
                for suf in ALLOWED_SUFFIXES:
                    if in_path.endswith(suf):
                        found=True
                        break
                if not found:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            out_name = get_stripped_name(in_path, opts['suffix'])
            if out_name is None:
                skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                exit_code=1
                return
            if os.path.exists(out_name) and not opts['force']:
                skip(f"{out_name} exists", opts['quiet'])
                exit_code=1
                return
        else:
            out_name=None

        has_junk,status = decompress_file_to_path(in_path, out_name, opts, to_stdout=opts['to_stdout'])
        if status!="ok":
            if status=="empty":
                skip(f"{in_path} empty", opts['quiet'])
            elif status=="unrecognized":
                skip(f"{in_path} unrecognized format", opts['quiet'])
            elif status=="notfound":
                skip(f"{in_path} does not exist", opts['quiet'])
            else:
                skip(f"{in_path} unrecognized format", opts['quiet'])
            exit_code=1
            return
        if has_junk:
            warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
            if opts['test']:
                exit_code=1
                return
        if not opts['keep'] and not opts['to_stdout'] and not is_test:
            try:
                os.remove(in_path)
            except:
                pass
        if opts['verbose']:
            if opts['to_stdout']:
                if not is_test:
                    sys.stderr.write(f"{in_path} to <stdout> \n")
            else:
                if not is_test and out_name:
                    sys.stderr.write(f"{in_path} to {out_name} \n")

    def process_test_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data=sys.stdin.buffer.read()
