            is_gzip = data[0:2]==b'\x1f\x8b' if len(data)>=2 else False
            is_zip = data[0:4]==b'PK\x03\x04' if len(data)>=4 else False
            is_zlib=False
            if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
                return
            try:
                if is_gzip:
                    pos=0
                    last=0
                    fd=data
                    while pos < len(fd):
                        if pos+2>len(fd) or fd[pos:pos+2]!=b'\x1f\x8b':
                            break
                        b=io.BytesIO(fd[pos:])
                        try:
                            with gzip.GzipFile(fileobj=b, mode='rb') as gg:
                                gg.read()
                                c=b.tell()
                                if c==0:
                                    break
                                last=pos+c
                                pos=last
                        except:
                            break
                    with gzip.GzipFile(fileobj=io.BytesIO(fd), mode='rb') as gf:
                        gf.read()
                    if last < len(fd):
                        warn(f"<stdin>: trailing junk was ignored", opts['quiet'])
                        exit_code=1
                elif is_zlib:
                    zlib.decompress(data)
                elif is_zip:
                    with zipfile.ZipFile(io.BytesIO(data)) as zf:
                        zf.testzip()
            except:
                warn(f"<stdin>: trailing junk was ignored", opts['quiet'])
                exit_code=1
            return

        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath=os.path.join(root,fname)
                        process_test_path(fpath)
                return
        try:
            if os.path.getsize(in_path)==0:
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
                return
        except:
            pass
        try:
            with open(in_path,'rb') as f:
                file_data=f.read()
            is_gzip = file_data[0:2]==b'\x1f\x8b' if len(file_data)>=2 else False
            is_zip = file_data[0:4]==b'PK\x03\x04' if len(file_data)>=4 else False
            is_zlib=False
            if len(file_data)>=2 and file_data[0]==0x78 and ((file_data[0]*256+file_data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip(f"{in_path} unrecognized format", opts['quiet'])
                exit_code=1
                return
            if is_gzip:
                pos=0
                last=0
                while pos < len(file_data):
                    if pos+2>len(file_data) or file_data[pos:pos+2]!=b'\x1f\x8b':
                        break
                    b=io.BytesIO(file_data[pos:])
                    try:
                        with gzip.GzipFile(fileobj=b, mode='rb') as gg:
                            gg.read()
                            c=b.tell()
                            if c==0:
                                break
                            last=pos+c
                            pos=last
                    except:
                        break
                try:
                    with gzip.GzipFile(fileobj=io.BytesIO(file_data), mode='rb') as gf:
                        gf.read()
                except:
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
                    return
                if last < len(file_data):
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
                    return
            elif is_zlib:
                try:
                    zlib.decompress(file_data)
                except:
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
            elif is_zip:
                try:
                    with zipfile.ZipFile(io.BytesIO(file_data)) as zf:
                        bad=zf.testzip()
                        if bad is not None:
                            warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                            exit_code=1
                except:
                    skip(f"{in_path} unrecognized format", opts['quiet'])
                    exit_code=1
        except Exception as e:
            skip(f"{in_path} unrecognized format", opts['quiet'])
            exit_code=1

    if not files:
        files=["-"]

    if is_test:
        for f in files:
            process_test_path(f)
    elif is_decompress:
        for f in files:
            process_decompress_path(f)
    else:
        for f in files:
            process_compress_path(f)

    sys.exit(exit_code)

if __name__=="__main__":
    main()
