    if data[0] != 0x1f or data[1] != 0x8b:
        return None
    flg = data[3]
    mtime = struct.unpack('<I', data[4:8])[0]
    idx = 10
    if flg & 0x04:
        if idx+2 > len(data):
            return None
        xlen = struct.unpack('<H', data[idx:idx+2])[0]
        idx += 2 + xlen
        if idx > len(data):
            return None
    fname = None
    comment = None
    if flg & 0x08:
        end = data.find(b'\x00', idx)
        if end == -1:
            return None
        fname = data[idx:end].decode('latin1', errors='ignore')
        idx = end+1
    if flg & 0x10:
        end = data.find(b'\x00', idx)
        if end == -1:
            return None
        comment = data[idx:end].decode('latin1', errors='ignore')
        idx = end+1
    if flg & 0x02:
        idx += 2
    return {'mtime': mtime, 'fname': fname, 'comment': comment, 'header_len': idx, 'flg': flg}

def get_output_suffix(opts):
    if opts['suffix'] is not None:
        return opts['suffix']
    if opts['zlib']:
        return ".zz"
    if opts['zip']:
        return ".zip"
    return ".gz"

def get_stripped_name(input_path, suffix_opt):
    if suffix_opt is not None:
        if not input_path.endswith(suffix_opt):
            return None
        prefix = input_path[:-len(suffix_opt)] if suffix_opt != "" else input_path
        if suffix_opt == ".tgz":
            return prefix + ".tar"
        return prefix
    else:
        for suf in sorted(ALLOWED_SUFFIXES, key=len, reverse=True):
            if input_path.endswith(suf):
                prefix = input_path[:-len(suf)]
                if suf == ".tgz":
                    return prefix + ".tar"
                return prefix
        return None

def compress_file_to_path(in_path, out_path, opts):
    with open(in_path, 'rb') as f:
        data = f.read()
    try:
        st = os.stat(in_path)
        mtime = int(st.st_mtime) if opts['store_time'] else 0
    except:
        mtime = 0
    fname = None
    if opts['store_name']:
        fname = os.path.basename(in_path)
    comment = opts['comment']
    level = opts['level']
    comp_level = level if level != 11 else 9
    if opts['zlib']:
        compressed = zlib.compress(data, comp_level)
        with open(out_path, 'wb') as out:
            out.write(compressed)
            if opts['sync']:
                out.flush()
                os.fsync(out.fileno())
    elif opts['zip']:
        entry_name = opts['alias'] if opts['alias'] else os.path.basename(in_path)
        with zipfile.ZipFile(out_path, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=comp_level) as zf:
            zi = zipfile.ZipInfo(entry_name)
            if opts['store_time'] and mtime != 0:
                dt = datetime.datetime.fromtimestamp(mtime)
                zi.date_time = (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)
            else:
                zi.date_time = (1980,1,1,0,0,0)
            if comment:
                zi.comment = comment.encode()
            if level == 0:
                zi.compress_type = zipfile.ZIP_STORED
            zf.writestr(zi, data)
        if opts['sync']:
            with open(out_path, 'ab') as f:
                f.flush()
                os.fsync(f.fileno())
    else:
        flg = 0
        if fname:
            flg |= 0x08
        if comment:
            flg |= 0x10
        xfl = 0
        if level == 9 or level == 11:
            xfl = 2
        elif level == 1:
            xfl = 4
        header = struct.pack('<BBBBLBB', 0x1f, 0x8b, 8, flg, mtime, xfl, 3)
        if fname:
            header += fname.encode('latin1', errors='ignore') + b'\x00'
        if comment:
            header += comment.encode('latin1', errors='ignore') + b'\x00'
        comp_obj = zlib.compressobj(comp_level, zlib.DEFLATED, -15)
        deflate_data = comp_obj.compress(data) + comp_obj.flush()
        crc = binascii.crc32(data) & 0xffffffff
        isize = len(data) & 0xffffffff
        trailer = struct.pack('<II', crc, isize)
        gz_data = header + deflate_data + trailer
        with open(out_path, 'wb') as out:
            out.write(gz_data)
            if opts['sync']:
                out.flush()
                os.fsync(out.fileno())

def compress_to_stdout_bytes(data, opts, input_name=None, is_file=False):
    mtime = 0
    fname = None
    if opts['store_name'] and is_file and input_name:
        fname = os.path.basename(input_name)
        if opts['store_time']:
            try:
                st = os.stat(input_name)
                mtime = int(st.st_mtime)
            except:
                mtime = int(time.time())
        else:
            mtime = 0
    comment = opts['comment']
    level = opts['level']
    comp_level = level if level != 11 else 9
    if opts['zlib']:
        compressed = zlib.compress(data, comp_level)
        sys.stdout.buffer.write(compressed)
    elif opts['zip']:
        entry_name = opts['alias'] if opts['alias'] else "-"
        if is_file and input_name and not opts['alias']:
            entry_name = os.path.basename(input_name)
        bio = io.BytesIO()
        with zipfile.ZipFile(bio, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=comp_level) as zf:
            zi = zipfile.ZipInfo(entry_name)
            if opts['store_time'] and is_file and input_name:
                try:
                    st = os.stat(input_name)
                    dt = datetime.datetime.fromtimestamp(st.st_mtime)
                    zi.date_time = (dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second)
                except:
                    zi.date_time = (1980,1,1,0,0,0)
            else:
                zi.date_time = (1980,1,1,0,0,0)
            if comment:
                zi.comment = comment.encode()
            if level == 0:
                zi.compress_type = zipfile.ZIP_STORED
            zf.writestr(zi, data)
        sys.stdout.buffer.write(bio.getvalue())
    else:
        flg = 0
        if fname:
            flg |= 0x08
        if comment:
            flg |= 0x10
        xfl = 0
        if level == 9 or level == 11:
            xfl = 2
        elif level == 1:
            xfl = 4
        header = struct.pack('<BBBBLBB', 0x1f, 0x8b, 8, flg, mtime, xfl, 3)
        if fname:
            header += fname.encode('latin1', errors='ignore') + b'\x00'
        if comment:
            header += comment.encode('latin1', errors='ignore') + b'\x00'
        comp_obj = zlib.compressobj(comp_level, zlib.DEFLATED, -15)
        deflate_data = comp_obj.compress(data) + comp_obj.flush()
        crc = binascii.crc32(data) & 0xffffffff
        isize = len(data) & 0xffffffff
        trailer = struct.pack('<II', crc, isize)
        sys.stdout.buffer.write(header + deflate_data + trailer)

def decompress_file_to_path(in_path, out_path, opts, to_stdout=False):
    try:
        st = os.stat(in_path)
        if st.st_size == 0:
            return None, "empty"
    except:
        return None, "notfound"
    try:
        with open(in_path, 'rb') as f:
            all_data = f.read()
    except:
        return None, "notfound"
    is_gzip = all_data[0:2] == b'\x1f\x8b' if len(all_data)>=2 else False
    is_zip = all_data[0:4] == b'PK\x03\x04' if len(all_data)>=4 else False
    is_zlib = False
    if len(all_data)>=2 and all_data[0]==0x78 and ((all_data[0]*256+all_data[1])%31==0):
        is_zlib=True
    if not (is_gzip or is_zip or is_zlib):
        return None, "unrecognized"
    try:
        if is_gzip:
            bio = io.BytesIO(all_data)
            with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                dec = gf.read()
            # Check trailing junk
            pos=0
            last=0
            file_data=all_data
            while pos < len(file_data):
                if pos+2>len(file_data) or file_data[pos:pos+2]!=b'\x1f\x8b':
                    break
                b = io.BytesIO(file_data[pos:])
                try:
                    with gzip.GzipFile(fileobj=b, mode='rb') as gg:
                        gg.read()
                        c=b.tell()
                        if c==0:
                            break
                        last=pos+c
                        pos=last
                except:
                    break
            has_junk = last < len(file_data)
            if to_stdout:
                sys.stdout.buffer.write(dec)
                return has_junk, "ok"
            else:
                with open(out_path, 'wb') as out:
                    out.write(dec)
                    if opts['sync']:
                        out.flush()
                        os.fsync(out.fileno())
                if opts['store_time']:
                    hdr = parse_gzip_header(all_data)
                    if hdr and hdr['mtime']!=0:
                        try:
                            os.utime(out_path, (hdr['mtime'], hdr['mtime']))
                        except:
                            pass
                else:
                    try:
                        os.utime(out_path, (st.st_atime, st.st_mtime))
                    except:
                        pass
                return has_junk, "ok"
        elif is_zlib:
            dec = zlib.decompress(all_data)
            if to_stdout:
                sys.stdout.buffer.write(dec)
            else:
                with open(out_path, 'wb') as out:
                    out.write(dec)
                    if opts['sync']:
                        out.flush()
                        os.fsync(out.fileno())
                try:
                    os.utime(out_path, (st.st_atime, st.st_mtime))
                except:
                    pass
            return False, "ok"
        elif is_zip:
            with zipfile.ZipFile(io.BytesIO(all_data), 'r') as zf:
                info = zf.infolist()[0]
                dec = zf.read(info.filename)
            if to_stdout:
                sys.stdout.buffer.write(dec)
            else:
                with open(out_path, 'wb') as out:
                    out.write(dec)
                    if opts['sync']:
                        out.flush()
                        os.fsync(out.fileno())
                if opts['store_time']:
                    try:
                        dt = datetime.datetime(*info.date_time)
                        mtime = dt.timestamp()
                        os.utime(out_path, (mtime, mtime))
                    except:
                        try:
                            os.utime(out_path, (st.st_atime, st.st_mtime))
                        except:
                            pass
                else:
                    try:
                        os.utime(out_path, (st.st_atime, st.st_mtime))
                    except:
                        pass
            return False, "ok"
    except Exception as e:
        return None, "unrecognized"

def list_files(file_list, verbose, quiet, recursive):
    # Expand directories if recursive, else keep as is for skip handling
    expanded = []
    for path in file_list:
        if path == "-":
            expanded.append(path)
            continue
        if os.path.isdir(path):
            if recursive:
                for root, dirs, filenames in os.walk(path):
                    for fname in filenames:
                        fpath = os.path.join(root, fname)
                        expanded.append(fpath)
            else:
                expanded.append(path)
        else:
            expanded.append(path)

    # First, separate valid and invalid for header decision
    # For stdin, we need to read data? But stdin for list: we can read stdin once and treat as valid if it has magic
    # For simplicity, we will handle stdin as valid for header printing if it contains data

    # We need to collect info about each expanded path: whether it's valid, and if valid, its listing info, and if invalid, skip message

    # We'll prepare lists
    valid_infos = []  # list of dicts for printing
    skip_messages = []

    # For stdin handling, we need to read stdin data if "-" in expanded
    stdin_data = None
    stdin_is_valid = False
    if "-" in expanded:
        # Read stdin
        stdin_data = sys.stdin.buffer.read()
        if len(stdin_data)==0:
            skip_messages.append("<stdin> empty")
        else:
            is_gzip = stdin_data[0:2]==b'\x1f\x8b' if len(stdin_data)>=2 else False
            is_zip = stdin_data[0:4]==b'PK\x03\x04' if len(stdin_data)>=4 else False
            is_zlib = False
            if len(stdin_data)>=2 and stdin_data[0]==0x78 and ((stdin_data[0]*256+stdin_data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip_messages.append("<stdin> unrecognized format")
            else:
                stdin_is_valid=True
                # We'll handle printing later, but for header decision, stdin counts as valid

    # Check other files for validity (for header decision, we need to know if any file is valid)
    # For each expanded path != "-"
    other_valid_exists = False
    for path in expanded:
        if path == "-":
            continue
        if not os.path.exists(path):
            skip_messages.append(f"{path} does not exist")
            continue
        if os.path.isdir(path):
            skip_messages.append(f"{path} is a directory")
            continue
        try:
            if os.path.getsize(path)==0:
                skip_messages.append(f"{path} empty")
                continue
        except:
            pass
        try:
            with open(path, 'rb') as f:
                file_data = f.read()
        except:
            skip_messages.append(f"{path} does not exist")
            continue
        is_gzip = file_data[0:2]==b'\x1f\x8b' if len(file_data)>=2 else False
        is_zip = file_data[0:4]==b'PK\x03\x04' if len(file_data)>=4 else False
        is_zlib = False
        if len(file_data)>=2 and file_data[0]==0x78 and ((file_data[0]*256+file_data[1])%31==0):
            is_zlib=True
        if not (is_gzip or is_zip or is_zlib):
            skip_messages.append(f"{path} unrecognized format")
            continue
        other_valid_exists=True

    has_valid = other_valid_exists or stdin_is_valid

    # If no valid, print skip messages and return 1
    if not has_valid:
        for msg in skip_messages:
            skip(msg, quiet)
        return 1

    # Print skip messages first (as per original behavior: skip messages before header)
    for msg in skip_messages:
        skip(msg, quiet)

    # Print header
    if verbose:
        print("method    check    timestamp    compressed   original reduced  name")
    else:
        print("compressed   original reduced  name")

    # Now process valid entries for actual listing
    # For stdin, if valid, list it
    if "-" in expanded and stdin_is_valid:
        # Use stdin_data already read
        data = stdin_data
        is_gzip = data[0:2]==b'\x1f\x8b'
        is_zip = data[0:4]==b'PK\x03\x04'
        is_zlib = False
        if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
            is_zlib=True
        if is_gzip:
            hdr = parse_gzip_header(data)
            if hdr:
                # Try to get deflate size
                try:
                    bio = io.BytesIO(data)
                    with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                        dec = gf.read()
                        consumed = bio.tell()
                    deflate_size = consumed - hdr['header_len'] - 8
                    orig = len(dec)
                    # Get crc
                    if len(data)>=8:
                        tr = data[consumed-8:consumed]
                        if len(tr)>=8:
                            crc = struct.unpack('<I', tr[0:4])[0]
                        else:
                            crc=0
                    else:
                        crc=0
                    check = "%08x" % crc
                    ts = format_timestamp(hdr['mtime'])
                    red = reduced_percent(deflate_size, orig)
                    if verbose:
                        print("%-6s  %8s  %12s  %10d %10d %7s  %s" % ("gzip 8", check, ts, deflate_size, orig, red, "<stdin>"))
                        if hdr['comment']:
                            print(hdr['comment'])
                    else:
                        print("%10d %10d %7s  %s" % (deflate_size, orig, red, "<stdin>"))
                except:
                    pass
        elif is_zlib:
            try:
                dec = zlib.decompress(data)
                comp = len(data)-6
                orig = 0
                red = " -inf%" if comp>0 else "  0.0%"
                adler = struct.unpack('>I', data[-4:])[0]
                check = "%08x" % adler
                ts = "------ -----"
                if verbose:
                    print("%-6s  %8s  %12s  %10d %10d %7s  %s" % ("zlib 8", check, ts, comp, orig, red, "<stdin>"))
                else:
                    print("%10d %10d %7s  %s" % (comp, orig, red, "<stdin>"))
            except:
                pass
        elif is_zip:
            try:
                with zipfile.ZipFile(io.BytesIO(data)) as zf:
                    entry_name = zf.infolist()[0].filename
                if verbose:
                    print("%-6s  %8s  %12s           0          0?  unk    %s" % ("zip  8", "--------", "------ -----", entry_name))
                else:
                    print("%10d          0?  unk    %s" % (0, entry_name))
            except:
                pass

    # For other files
    for path in expanded:
        if path == "-":
            continue
        if not os.path.exists(path):
            continue
        if os.path.isdir(path):
            continue
        try:
            if os.path.getsize(path)==0:
                continue
        except:
            continue
        try:
            with open(path, 'rb') as f:
                file_data = f.read()
        except:
            continue
        is_gzip = file_data[0:2]==b'\x1f\x8b' if len(file_data)>=2 else False
        is_zip = file_data[0:4]==b'PK\x03\x04' if len(file_data)>=4 else False
        is_zlib = False
        if len(file_data)>=2 and file_data[0]==0x78 and ((file_data[0]*256+file_data[1])%31==0):
            is_zlib=True
        if not (is_gzip or is_zip or is_zlib):
            continue

        if is_gzip:
            pos=0
            total_comp=0
            total_orig=0
            first_hdr=None
            first_crc=0
            members=0
            last_pos=0
            while pos < len(file_data):
                if pos+10>len(file_data) or file_data[pos:pos+2]!=b'\x1f\x8b':
                    break
                hdr = parse_gzip_header(file_data[pos:])
                if hdr is None:
                    break
                hl = hdr['header_len']
                bio = io.BytesIO(file_data[pos:])
                try:
                    with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                        dec = gf.read()
                        consumed = bio.tell()
                        if consumed==0:
                            break
                        tr = file_data[pos+consumed-8:pos+consumed]
                        if len(tr)<8:
                            break
                        crc = struct.unpack('<I', tr[0:4])[0]
                        isize = struct.unpack('<I', tr[4:8])[0]
                        defl = consumed - hl - 8
                        total_comp+=defl
                        total_orig+=isize
                        if first_hdr is None:
                            first_hdr=hdr
                            first_crc=crc
                        members+=1
                        last_pos=pos+consumed
                        pos=last_pos
                except:
                    break
            if members==0:
                continue
            base = os.path.basename(path)
            stripped = None
            for suf in sorted(ALLOWED_SUFFIXES, key=len, reverse=True):
                if base.endswith(suf):
                    stripped = base[:-len(suf)]
                    if suf==".tgz":
                        stripped = stripped+".tar"
                    break
            if stripped is None:
                stripped = base
            if members==1:
                comp=total_comp
                orig=total_orig
                check="%08x" % first_crc
                ts=format_timestamp(first_hdr['mtime'])
                red=reduced_percent(comp, orig)
                if verbose:
                    print("%-6s  %8s  %12s  %10d %10d %7s  %s" % ("gzip 8", check, ts, comp, orig, red, stripped))
                    if first_hdr['comment']:
                        print(first_hdr['comment'])
                else:
                    print("%10d %10d %7s  %s" % (comp, orig, red, stripped))
            else:
                # Multi-member: for simplicity, show as single with total
                comp=total_comp
                orig=total_orig
                check="%08x" % first_crc
                ts=format_timestamp(first_hdr['mtime']) if first_hdr else "------ -----"
                red=reduced_percent(comp, orig)
                # For multi, pigz shows "0?  unk"?? We will just show normal
                if verbose:
                    print("%-6s  %8s  %12s  %10d %10d %7s  %s" % ("gzip 8", check, ts, comp, orig, red, stripped))
                    if first_hdr and first_hdr['comment']:
                        print(first_hdr['comment'])
                else:
                    print("%10d %10d %7s  %s" % (comp, orig, red, stripped))
        elif is_zlib:
            comp = len(file_data)-6 if len(file_data)>=6 else len(file_data)
            orig=0
            red=" -inf%" if comp>0 else "  0.0%"
            try:
                adler = struct.unpack('>I', file_data[-4:])[0]
                check="%08x" % adler
            except:
                check="00000000"
            ts="------ -----"
            base=os.path.basename(path)
            stripped=None
            for suf in sorted(ALLOWED_SUFFIXES, key=len, reverse=True):
                if base.endswith(suf):
                    stripped=base[:-len(suf)]
                    break
            if stripped is None:
                stripped=base
            if verbose:
                print("%-6s  %8s  %12s  %10d %10d %7s  %s" % ("zlib 8", check, ts, comp, orig, red, stripped))
            else:
                print("%10d %10d %7s  %s" % (comp, orig, red, stripped))
        elif is_zip:
            try:
                with zipfile.ZipFile(io.BytesIO(file_data), 'r') as zf:
                    info = zf.infolist()[0]
                    entry_name = info.filename
                    # For zip from file, name is stripped (original file name) or entry name? In pigz, for file a.txt.zip, name is a.txt (stripped), not entry name? Actually entry name is a.txt, same as stripped. For stdin zip, entry name is "-" or alias, and stripped would be "out" (from out.zip) but pigz shows "-" or alias, not "out". So for zip, name should be entry name, not stripped.
                    # Let's use entry_name for display
                    display_name = entry_name
                    # But for file a.txt.zip, entry_name is a.txt, which matches stripped
                    # For out.zip from stdin, entry_name is "-" (or alias), matches observed
                    if verbose:
                        try:
                            dt = datetime.datetime(*info.date_time)
                            if info.date_time == (1980,1,1,0,0,0):
                                ts="------ -----"
                            else:
                                ts=format_timestamp(dt.timestamp())
                        except:
                            ts="------ -----"
                        print("%-6s  %8s  %12s           0          0?  unk    %s" % ("zip  8", "--------", ts, display_name))
                    else:
                        print("%10d          0?  unk    %s" % (0, display_name))
            except:
                continue

    # Determine exit code: if any skip messages, exit 1, else 0
    if skip_messages:
        return 1
    return 0

def main():
    default_decompress = "unpigz" in os.path.basename(sys.argv[0])

    env_args=[]
    for envvar in ("GZIP","PIGZ"):
        v=os.environ.get(envvar)
        if v:
            try:
                env_args.extend(shlex.split(v))
            except:
                env_args.extend(v.split())

    raw_args = env_args + sys.argv[1:]

    opts = {
        'decompress': default_decompress,
        'to_stdout': False,
        'force': False,
        'keep': False,
        'list': False,
        'test': False,
        'verbose': False,
        'quiet': False,
        'recursive': False,
        'independent': False,
        'rsyncable': False,
        'huffman': False,
        'rle': False,
        'zip': False,
        'zlib': False,
        'first': False,
        'oneblock': False,
        'sync': False,
        'blocksize': 128,
        'processes': None,
        'iterations': 15,
        'maxsplits': 15,
        'alias': None,
        'comment': None,
        'suffix': None,
        'level': 6,
        'help': False,
        'version': False,
        'license': False,
        'store_name': True,
        'store_time': True,
    }

    name_flag = None
    time_flag = None
    first_hvl = None
    last_dt = None
    list_seen=False
    files=[]
    after_dashdash=False
    idx=0
    while idx < len(raw_args):
        arg=raw_args[idx]
        if after_dashdash:
            files.append(arg)
            idx+=1
            continue
        if arg=="--":
            after_dashdash=True
            idx+=1
            continue
        if arg=="-":
            files.append(arg)
            idx+=1
            continue
        if arg.startswith("--"):
            if "=" in arg:
                abort(f"invalid option: {arg}")
            name=arg[2:]
            if name=="help":
                opts['help']=True
                if first_hvl is None:
                    first_hvl='h'
            elif name=="version":
                opts['version']=True
                if first_hvl is None:
                    first_hvl='V'
            elif name=="license":
                opts['license']=True
                if first_hvl is None:
                    first_hvl='L'
            elif name in ("stdout","to-stdout"):
                opts['to_stdout']=True
            elif name in ("decompress","uncompress"):
                opts['decompress']=True
                last_dt='d'
            elif name=="force":
                opts['force']=True
            elif name=="first":
                opts['first']=True
            elif name=="huffman":
                opts['huffman']=True
            elif name=="independent":
                opts['independent']=True
            elif name=="keep":
                opts['keep']=True
            elif name=="zip":
                opts['zip']=True
            elif name=="list":
                opts['list']=True
                list_seen=True
            elif name=="no-time":
                time_flag=False
            elif name=="time":
                time_flag=True
            elif name=="no-name":
                name_flag=False
                time_flag=False
            elif name=="name":
                name_flag=True
                time_flag=True
            elif name=="oneblock":
                opts['oneblock']=True
            elif name in ("quiet","silent"):
                opts['quiet']=True
            elif name=="recursive":
                opts['recursive']=True
            elif name=="rsyncable":
                opts['rsyncable']=True
            elif name=="test":
                opts['test']=True
                last_dt='t'
            elif name=="rle":
                opts['rle']=True
            elif name=="verbose":
                opts['verbose']=True
            elif name=="synchronous":
                opts['sync']=True
            elif name=="zlib":
                opts['zlib']=True
            elif name=="fast":
                opts['level']=1
            elif name=="best":
                opts['level']=9
            elif name in ("alias","comment","blocksize","processes","suffix","iterations","maxsplits"):
                if idx+1 >= len(raw_args):
                    short_map={"alias":"A","comment":"C","blocksize":"b","processes":"p","suffix":"S","iterations":"I","maxsplits":"J"}
                    abort(f"missing parameter after -{short_map[name]}")
                val=raw_args[idx+1]
                if name=="alias":
                    opts['alias']=val
                elif name=="comment":
                    opts['comment']=val
                elif name=="blocksize":
                    v=parse_numeric_param(val)
                    if v<32:
                        abort("block size too small (must be >= 32K)")
                    opts['blocksize']=v
                elif name=="processes":
                    v=parse_numeric_param(val)
                    if v<=0:
                        abort(f"invalid number of processes: {v}")
                    opts['processes']=v
                elif name=="suffix":
                    opts['suffix']=val
                elif name=="iterations":
                    v=parse_numeric_param(val)
                    opts['iterations']=v
                elif name=="maxsplits":
                    v=parse_numeric_param(val)
                    opts['maxsplits']=v
                idx+=1
            else:
                abort(f"invalid option: --{name}")
            idx+=1
            continue
        elif arg.startswith("-") and len(arg)>1:
            j=1
            while j < len(arg):
                ch=arg[j]
                if ch.isdigit():
                    num_str=""
                    k=j
                    while k < len(arg) and arg[k].isdigit():
                        num_str+=arg[k]
                        k+=1
                    if num_str in [str(d) for d in range(10)]+["11"]:
                        opts['level']=int(num_str)
                        j=k
                        continue
                    else:
                        abort("only levels 0..9 and 11 are allowed")
                if ch in ('A','b','C','I','J','p','S'):
                    remainder=arg[j+1:]
                    if ch in ('S','C'):
                        if remainder!="":
                            abort(f"invalid usage: -{ch} must be followed by space")
                        if idx+1 >= len(raw_args):
                            abort(f"missing parameter after -{ch}")
                        param=raw_args[idx+1]
                        if ch=='S':
                            opts['suffix']=param
                        else:
                            opts['comment']=param
                        idx+=1
                        break
                    else:
                        if remainder!="":
                            param=remainder
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            break
                        else:
                            if idx+1 >= len(raw_args):
                                abort(f"missing parameter after -{ch}")
                            param=raw_args[idx+1]
                            if ch=='A':
                                opts['alias']=param
                            elif ch=='b':
                                v=parse_numeric_param(param)
                                if v<32:
                                    abort("block size too small (must be >= 32K)")
                                opts['blocksize']=v
                            elif ch=='p':
                                v=parse_numeric_param(param)
                                if v<=0:
                                    abort(f"invalid number of processes: {v}")
                                opts['processes']=v
                            elif ch=='I':
                                v=parse_numeric_param(param)
                                opts['iterations']=v
                            elif ch=='J':
                                v=parse_numeric_param(param)
                                opts['maxsplits']=v
                            idx+=1
                            break
                else:
                    if ch=='c':
                        opts['to_stdout']=True
                    elif ch=='d':
                        opts['decompress']=True
                        last_dt='d'
                    elif ch=='f':
                        opts['force']=True
                    elif ch=='h':
                        opts['help']=True
                        if first_hvl is None:
                            first_hvl='h'
                    elif ch=='H':
                        opts['huffman']=True
                    elif ch=='i':
                        opts['independent']=True
                    elif ch=='k':
                        opts['keep']=True
                    elif ch=='K':
                        opts['zip']=True
                    elif ch=='l':
                        opts['list']=True
                        list_seen=True
                    elif ch=='L':
                        opts['license']=True
                        if first_hvl is None:
                            first_hvl='L'
                    elif ch=='m':
                        time_flag=False
                    elif ch=='M':
                        time_flag=True
                    elif ch=='n':
                        name_flag=False
                        time_flag=False
                    elif ch=='N':
                        name_flag=True
                        time_flag=True
                    elif ch=='O':
                        opts['oneblock']=True
                    elif ch=='q':
                        opts['quiet']=True
                    elif ch=='r':
                        opts['recursive']=True
                    elif ch=='R':
                        opts['rsyncable']=True
                    elif ch=='t':
                        opts['test']=True
                        last_dt='t'
                    elif ch=='U':
                        opts['rle']=True
                    elif ch=='v':
                        opts['verbose']=True
                    elif ch=='V':
                        opts['version']=True
                        if first_hvl is None:
                            first_hvl='V'
                    elif ch=='Y':
                        opts['sync']=True
                    elif ch=='z':
                        opts['zlib']=True
                    elif ch=='F':
                        opts['first']=True
                    else:
                        abort(f"invalid option: -{ch}")
                    j+=1
            idx+=1
            continue
        else:
            files.append(arg)
            idx+=1

    if first_hvl is not None:
        if first_hvl=='h':
            sys.stdout.write(HELP_TEXT)
            sys.exit(0)
        elif first_hvl=='V':
            if opts['verbose']:
                sys.stdout.write(f"pigz {VERSION}\nzlib {ZLIB_VERSION}\n")
            else:
                sys.stdout.write(f"pigz {VERSION}\n")
            sys.exit(0)
        elif first_hvl=='L':
            sys.stdout.write(LICENSE_TEXT)
            sys.exit(0)

    if opts['list']:
        if not files:
            files=["-"]
        code = list_files(files, opts['verbose'], opts['quiet'], opts['recursive'])
        sys.exit(code)

    is_decompress=False
    is_test=False
    if last_dt is not None:
        if last_dt=='d':
            is_decompress=True
        else:
            is_test=True
    else:
        is_decompress=opts['decompress']
        is_test=opts['test']

    if not is_decompress and not is_test:
        final_name = name_flag if name_flag is not None else True
        final_time = time_flag if time_flag is not None else True
    else:
        final_name = name_flag if name_flag is not None else False
        final_time = time_flag if time_flag is not None else False
    opts['store_name']=final_name
    opts['store_time']=final_time
    opts['test']=is_test

    comp_suffix = get_output_suffix(opts)

    exit_code=0

    def process_compress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write("<stdin> to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=None, is_file=False)
            return
        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath = os.path.join(root, fname)
                        process_compress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if in_path.endswith(comp_suffix) and not opts['force']:
            skip(f"{in_path} ends with {comp_suffix}", opts['quiet'])
            return
        out_path = in_path + comp_suffix
        if not opts['to_stdout']:
            if os.path.exists(out_path) and not opts['force']:
                skip(f"{out_path} exists", opts['quiet'])
                exit_code=1
                return
        try:
            with open(in_path, 'rb') as f:
                data=f.read()
        except:
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if opts['to_stdout']:
            if sys.stdout.isatty() and not opts['force']:
                abort("trying to write compressed data to a terminal (use -f to force)")
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to <stdout> \n")
            compress_to_stdout_bytes(data, opts, input_name=in_path, is_file=True)
        else:
            if opts['verbose']:
                sys.stderr.write(f"{in_path} to {out_path} \n")
            try:
                compress_file_to_path(in_path, out_path, opts)
            except Exception as e:
                skip(f"{out_path} exists" if os.path.exists(out_path) else str(e), opts['quiet'])
                exit_code=1
                return
            if not opts['keep']:
                try:
                    os.remove(in_path)
                except:
                    pass

    def process_decompress_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data = sys.stdin.buffer.read()
            if len(data)==0:
                skip("<stdin> empty", opts['quiet'])
                exit_code=1
                return
            is_gzip = data[0:2]==b'\x1f\x8b' if len(data)>=2 else False
            is_zip = data[0:4]==b'PK\x03\x04' if len(data)>=4 else False
            is_zlib = False
            if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
                return
            try:
                if is_gzip:
                    bio = io.BytesIO(data)
                    with gzip.GzipFile(fileobj=bio, mode='rb') as gf:
                        dec=gf.read()
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zlib:
                    dec=zlib.decompress(data)
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
                elif is_zip:
                    with zipfile.ZipFile(io.BytesIO(data)) as zf:
                        dec=zf.read(zf.infolist()[0].filename)
                    if opts['test']:
                        return
                    sys.stdout.buffer.write(dec)
                    if opts['verbose']:
                        sys.stderr.write("<stdin> to <stdout> \n")
            except:
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
            return

        if os.path.islink(in_path) and not opts['force']:
            skip(f"{in_path} is a symbolic link", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath=os.path.join(root,fname)
                        process_decompress_path(fpath)
                return
        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        try:
            if os.path.getsize(in_path)==0:
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
                return
        except:
            pass

        if not opts['to_stdout']:
            # Suffix check
            if opts['suffix'] is not None:
                if not in_path.endswith(opts['suffix']):
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
                if opts['suffix'] not in ALLOWED_SUFFIXES:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            else:
                found=False
                for suf in ALLOWED_SUFFIXES:
                    if in_path.endswith(suf):
                        found=True
                        break
                if not found:
                    skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                    exit_code=1
                    return
            out_name = get_stripped_name(in_path, opts['suffix'])
            if out_name is None:
                skip(f"{in_path} does not have compressed suffix", opts['quiet'])
                exit_code=1
                return
            if os.path.exists(out_name) and not opts['force']:
                skip(f"{out_name} exists", opts['quiet'])
                exit_code=1
                return
        else:
            out_name=None

        has_junk,status = decompress_file_to_path(in_path, out_name, opts, to_stdout=opts['to_stdout'])
        if status!="ok":
            if status=="empty":
                skip(f"{in_path} empty", opts['quiet'])
            elif status=="unrecognized":
                skip(f"{in_path} unrecognized format", opts['quiet'])
            elif status=="notfound":
                skip(f"{in_path} does not exist", opts['quiet'])
            else:
                skip(f"{in_path} unrecognized format", opts['quiet'])
            exit_code=1
            return
        if has_junk:
            warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
            if opts['test']:
                exit_code=1
                return
        if not opts['keep'] and not opts['to_stdout'] and not is_test:
            try:
                os.remove(in_path)
            except:
                pass
        if opts['verbose']:
            if opts['to_stdout']:
                if not is_test:
                    sys.stderr.write(f"{in_path} to <stdout> \n")
            else:
                if not is_test and out_name:
                    sys.stderr.write(f"{in_path} to {out_name} \n")

    def process_test_path(in_path):
        nonlocal exit_code
        if in_path=="-":
            data=sys.stdin.buffer.read()
            if len(data)==0:
                skip("<stdin> empty", opts['quiet'])
                exit_code=1
                return
            is_gzip = data[0:2]==b'\x1f\x8b' if len(data)>=2 else False
            is_zip = data[0:4]==b'PK\x03\x04' if len(data)>=4 else False
            is_zlib=False
            if len(data)>=2 and data[0]==0x78 and ((data[0]*256+data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip("<stdin> unrecognized format", opts['quiet'])
                exit_code=1
                return
            try:
                if is_gzip:
                    pos=0
                    last=0
                    fd=data
                    while pos < len(fd):
                        if pos+2>len(fd) or fd[pos:pos+2]!=b'\x1f\x8b':
                            break
                        b=io.BytesIO(fd[pos:])
                        try:
                            with gzip.GzipFile(fileobj=b, mode='rb') as gg:
                                gg.read()
                                c=b.tell()
                                if c==0:
                                    break
                                last=pos+c
                                pos=last
                        except:
                            break
                    with gzip.GzipFile(fileobj=io.BytesIO(fd), mode='rb') as gf:
                        gf.read()
                    if last < len(fd):
                        warn(f"<stdin>: trailing junk was ignored", opts['quiet'])
                        exit_code=1
                elif is_zlib:
                    zlib.decompress(data)
                elif is_zip:
                    with zipfile.ZipFile(io.BytesIO(data)) as zf:
                        zf.testzip()
            except:
                warn(f"<stdin>: trailing junk was ignored", opts['quiet'])
                exit_code=1
            return

        if not os.path.exists(in_path):
            skip(f"{in_path} does not exist", opts['quiet'])
            exit_code=1
            return
        if os.path.isdir(in_path):
            if not opts['recursive']:
                skip(f"{in_path} is a directory", opts['quiet'])
                exit_code=1
                return
            else:
                for root, dirs, filenames in os.walk(in_path):
                    for fname in filenames:
                        fpath=os.path.join(root,fname)
                        process_test_path(fpath)
                return
        try:
            if os.path.getsize(in_path)==0:
                skip(f"{in_path} empty", opts['quiet'])
                exit_code=1
                return
        except:
            pass
        try:
            with open(in_path,'rb') as f:
                file_data=f.read()
            is_gzip = file_data[0:2]==b'\x1f\x8b' if len(file_data)>=2 else False
            is_zip = file_data[0:4]==b'PK\x03\x04' if len(file_data)>=4 else False
            is_zlib=False
            if len(file_data)>=2 and file_data[0]==0x78 and ((file_data[0]*256+file_data[1])%31==0):
                is_zlib=True
            if not (is_gzip or is_zip or is_zlib):
                skip(f"{in_path} unrecognized format", opts['quiet'])
                exit_code=1
                return
            if is_gzip:
                pos=0
                last=0
                while pos < len(file_data):
                    if pos+2>len(file_data) or file_data[pos:pos+2]!=b'\x1f\x8b':
                        break
                    b=io.BytesIO(file_data[pos:])
                    try:
                        with gzip.GzipFile(fileobj=b, mode='rb') as gg:
                            gg.read()
                            c=b.tell()
                            if c==0:
                                break
                            last=pos+c
                            pos=last
                    except:
                        break
                try:
                    with gzip.GzipFile(fileobj=io.BytesIO(file_data), mode='rb') as gf:
                        gf.read()
                except:
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
                    return
                if last < len(file_data):
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
                    return
            elif is_zlib:
                try:
                    zlib.decompress(file_data)
                except:
                    warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                    exit_code=1
            elif is_zip:
                try:
                    with zipfile.ZipFile(io.BytesIO(file_data)) as zf:
                        bad=zf.testzip()
                        if bad is not None:
                            warn(f"{in_path}: trailing junk was ignored", opts['quiet'])
                            exit_code=1
                except:
                    skip(f"{in_path} unrecognized format", opts['quiet'])
                    exit_code=1
        except Exception as e:
            skip(f"{in_path} unrecognized format", opts['quiet'])
            exit_code=1

    if not files:
        files=["-"]

    if is_test:
        for f in files:
            process_test_path(f)
    elif is_decompress:
        for f in files:
            process_decompress_path(f)
    else:
        for f in files:
            process_compress_path(f)

    sys.exit(exit_code)

if __name__=="__main__":
    main()
